// 02 - Link & DHCP: RGMII auto-negotiation and the lwIP DHCP lease.
// One suite, one file: it registers itself with the runner; there is no
// list of suites to keep in step with the files.
// GENERATED by micro-os-scaffold (--micro-test-plus).
#include <mtp_board.hpp>
#include "eth_helpers.hpp"

using namespace os::rtos;
using namespace mtp_eth;

// 02 - Link & DHCP
// ===========================================================================
mt::static_suite suite_link_dhcp{
  "02 - Link & DHCP", mtp_board::runner (),
  [] (mt::suite& ts) {
    ts.test ("RGMII physical link auto-negotiated", [] (auto& t) {
      const unsigned spd = genet::speed ();
      const bool fdx = genet::full_duplex ();
      std::printf ("# link: %s, %u Mbit/s %s duplex\n",
                   g_up.link ? "up" : "down", spd, fdx ? "full" : "half");
      t.expect (g_up.link && net::link_up () && genet::linked ())
          << "RGMII link is up";
      t.expect (spd == 10u || spd == 100u || spd == 1000u)
          << fmt ("negotiated speed %u Mbit/s", spd);
    });

    ts.test ("lwIP netif configured with IPv4 address and gateway", [] (auto& t) {
      const std::uint32_t ip = net::address ();
      const std::uint32_t gw = net::gateway ();
      std::printf ("# IPv4 %u.%u.%u.%u (%s), gateway %u.%u.%u.%u\n",
                   static_cast<unsigned> ((ip >> 24) & 0xffu),
                   static_cast<unsigned> ((ip >> 16) & 0xffu),
                   static_cast<unsigned> ((ip >> 8) & 0xffu),
                   static_cast<unsigned> (ip & 0xffu),
                   g_up.leased ? "DHCP" : "static",
                   static_cast<unsigned> ((gw >> 24) & 0xffu),
                   static_cast<unsigned> ((gw >> 16) & 0xffu),
                   static_cast<unsigned> ((gw >> 8) & 0xffu),
                   static_cast<unsigned> (gw & 0xffu));
      t.expect (g_up.address && net::has_address ())
          << (g_up.leased ? "IPv4 lease acquired via DHCP"
                          : "static IPv4 address configured");
      t.expect (mt::ne (ip, 0u)) << fmt_ip ("interface IPv4", ip);
      t.expect (mt::ne (gw, 0u)) << fmt_ip ("gateway IPv4", gw);
      t.expect (mt::ne (ip, gw))
          << "interface IPv4 is distinct from gateway IPv4";
    });
  }
};
